components.css:
.ds-btn-primary {
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
  height:40px; padding:0 18px; border:0; border-radius:10px;
  background:#0F7A66; color:#FFFFFF; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  font-size:14px; font-weight:650; line-height:1; cursor:pointer;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.16);
  transition:background-color 160ms cubic-bezier(.22,1,.36,1), transform 160ms cubic-bezier(.22,1,.36,1);
}
.ds-btn-primary:hover { background:#0B6857; transform:translateY(-1px); }
.ds-btn-primary:active { background:#085545; transform:translateY(0); }
.ds-btn-primary:focus-visible { outline:2px solid #0F7A66; outline-offset:2px; }

.ds-btn-secondary {
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
  height:40px; padding:0 18px; border:1px solid #C7D5CF; border-radius:10px;
  background:#FFFFFF; color:#17231F; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  font-size:14px; font-weight:650; line-height:1; cursor:pointer;
  transition:background-color 160ms cubic-bezier(.22,1,.36,1), border-color 160ms cubic-bezier(.22,1,.36,1), transform 160ms cubic-bezier(.22,1,.36,1);
}
.ds-btn-secondary:hover { background:#FAFCFB; border-color:#7C8F87; transform:translateY(-1px); }

.ds-input {
  width:100%; height:42px; padding:1px 12px; border:0; border-radius:10px;
  background:#FFFFFF; color:#17231F; box-shadow:0 0 0 1px #C7D5CF inset;
  font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size:14px; outline:none;
}
.ds-input::placeholder { color:#5F6F69; }
.ds-input:focus { box-shadow:0 0 0 1px #0F7A66 inset, 0 0 0 3px rgba(15,122,102,.16); }

.ds-card {
  background:#FFFFFF; border:1px solid #E0E8E4; border-radius:14px; padding:20px;
  color:#17231F; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size:14px; line-height:1.65;
}
.ds-card h3 { margin:0 0 6px; font-size:16px; font-weight:700; letter-spacing:-.015em; }
.ds-card p { margin:0; color:#4C5D57; }
.ds-card--interactive:hover { transform:translateY(-2px); border-color:#C7D5CF; box-shadow:0 2px 4px rgba(23,35,31,.04), 0 18px 40px -20px rgba(23,35,31,.26); }

.ds-chip {
  display:inline-flex; align-items:center; gap:5px; padding:3px 10px;
  border-radius:999px; background:#EDF2EF; color:#4C5D57;
  font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif; font-size:12px; font-weight:650; line-height:1.6;
}
.ds-chip--primary { background:#E8F4F0; color:#085545; }
.ds-chip--success { background:#E8F4F0; color:#0F7A66; }
.ds-chip--warning { background:#FBF3E3; color:#8A5700; }
.ds-chip--danger { background:#FAEBE9; color:#B33A32; }

.ds-tint {
  position:relative; overflow:hidden; border-radius:16px; padding:32px;
  background:#F2F9F7; border:1px solid #D8EAE5; color:#17231F; font-family:Manrope, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
}
.ds-tint h1 { margin:12px 0 8px; font-size:30px; font-weight:700; letter-spacing:-.025em; color:#17231F; }
.ds-tint p { margin:0; max-width:56ch; color:#4C5D57; font-size:13.5px; line-height:1.7; }
.ds-tint::after { content:''; position:absolute; right:-80px; top:-100px; width:320px; height:320px; border:1px solid rgba(15,122,102,.12); border-radius:50%; }

.ds-loader { position:fixed; inset:0; z-index:100; display:grid; place-items:center; background:color-mix(in srgb,#F4F7F5 68%,transparent); backdrop-filter:blur(10px) saturate(115%); color:#17231F; }
.ds-loader__mark { display:flex; width:46px; height:46px; align-items:center; justify-content:center; border-radius:14px; background:#17231F; color:#0F7A66; }
.ds-loader p { margin:14px 0 0; font-size:12.5px; font-weight:600; color:#5F6F69; }
.ds-loader__bar { display:block; width:112px; height:2px; margin-top:14px; overflow:hidden; border-radius:999px; background:#E8F4F0; }
.ds-loader__bar span { display:block; width:40%; height:100%; border-radius:inherit; background:#0F7A66; animation:ds-loader-slide 1.15s cubic-bezier(.22,1,.36,1) infinite; }
@keyframes ds-loader-slide { from { transform:translateX(-120%); } to { transform:translateX(320%); } }
